INSERT INTO tele_sites (site_id, email, config) VALUES ('brightside-dental-studio', 'hello@brightside.com', '{"siteId":"brightside-dental-studio","target":"cloudflare","specialty":"dental","specialtyLabel":"Dental practice","businessName":"Brightside Dental Studio","brandName":"Brightside Dental","location":"Quezon City, Philippines","email":"hello@brightside.com","phone":"+63 2 8123 4567","timeZone":"Asia/Manila","theme":"brivon-light","editorialAccent":"black","primaryColor":"#506f00","accentColor":"#506f00","paperColor":"#f5f5ef","fontStyle":"serif","features":{"blog":true,"gallery":true,"scheduling":true},"payments":{"gcashName":"Brightside Dental Studio","gcashNumber":"+63 917 555 0134","mayaName":"Brightside Dental Studio","mayaNumber":"+63 918 555 0142"},"customPages":[],"menuLinks":[{"id":"home","label":"Welcome","href":"/#home"},{"id":"care","label":"Our care","href":"/#care"},{"id":"about","label":"Our approach","href":"/#about"},{"id":"gallery","label":"Gallery","href":"/#gallery","feature":"gallery"},{"id":"journal","label":"Journal","href":"/#journal","feature":"blog"},{"id":"appointments","label":"Appointments","href":"/appointments.html","feature":"scheduling"},{"id":"contact","label":"Contact","href":"/#contact"}],"pageEdits":[{"selector":"em","index":0,"text":"BUILD BIZ"},{"selector":"div.hero-art-shape","index":0,"text":""},{"selector":"h3.service-title","index":1,"text":"NEW BUSINESS "},{"selector":"h3.service-title","index":0,"text":"PREVENTIVE SAAS"}],"heroEyebrow":"A BRIGHTER KIND OF DENTAL CARE","heroHeadline":"A reason to\nsmile easier.","heroText":"Modern, thoughtful dentistry with your comfort at the center.","services":["Preventive care","Restorative dentistry","Cosmetic treatments"],"demoPosts":[{"title":"A gentler start to your first visit","slug":"a-gentler-first-visit","excerpt":"A few simple ways we make a new-patient appointment feel clear and calm.","category":"First visits","body":"A first visit should feel like a conversation, not a checklist. We will take time to hear what matters to you, explain what we see, and make room for questions before deciding on any next steps.","id":"sample-1","featureImageUrl":"/images/blog-welcome.svg","featureImageAlt":"An open, welcoming practice doorway","publishedAt":"2026-10-13T12:32:15.083Z"},{"title":"Small habits for a healthier smile","slug":"small-habits-healthier-smile","excerpt":"A steady routine can make looking after your smile feel more manageable.","category":"Everyday care","body":"A consistent brush-and-floss routine, regular checkups, and honest conversations can go a long way. If something feels confusing, bring it up at your next visit. Good care starts with understanding.","id":"sample-2","featureImageUrl":"/images/blog-small-moments.svg","featureImageAlt":"A sunlit still life with a flower and warm cup","publishedAt":"2026-10-04T12:32:15.083Z"},{"title":"What to expect at a checkup","slug":"what-to-expect-at-a-checkup","excerpt":"Knowing what happens next can make a routine appointment feel easier.","category":"Your visit","body":"We will review your concerns, explain what we are checking, and pause whenever you need. You will leave with a clear summary and a chance to talk through any options.","id":"sample-3","featureImageUrl":"/images/blog-care-team.svg","featureImageAlt":"A practice team and companion in a calm room","publishedAt":"2026-09-25T12:32:15.083Z"}],"demoGallery":[{"title":"A warm welcome","imageUrl":"","altText":"Illustrated gallery placeholder for a welcoming practice space","caption":"A friendly first impression starts at the door.","category":"Practice life","sortOrder":1,"status":"published"},{"title":"Care, at every stage","imageUrl":"","altText":"Illustrated gallery placeholder for a care moment","caption":"Thoughtful care for the everyday and the unexpected.","category":"Our approach","sortOrder":2,"status":"published"},{"title":"A little time to listen","imageUrl":"","altText":"Illustrated gallery placeholder for a conversation with the care team","caption":"Questions welcome. We will take the time.","category":"Team","sortOrder":3,"status":"published"}],"createdAt":"2026-10-22T12:32:15.083Z"}'::jsonb) ON CONFLICT (site_id) DO NOTHING;
INSERT INTO tele_blog_posts (site_id, title, slug, excerpt, body, feature_image_url, feature_image_alt, category, status, published_at) VALUES ('brightside-dental-studio', 'A gentler start to your first visit', 'a-gentler-first-visit', 'A few simple ways we make a new-patient appointment feel clear and calm.', 'A first visit should feel like a conversation, not a checklist. We will take time to hear what matters to you, explain what we see, and make room for questions before deciding on any next steps.', '/images/blog-welcome.svg', 'An open, welcoming practice doorway', 'First visits', 'published', now()) ON CONFLICT (site_id, slug) DO NOTHING;
INSERT INTO tele_blog_posts (site_id, title, slug, excerpt, body, feature_image_url, feature_image_alt, category, status, published_at) VALUES ('brightside-dental-studio', 'Small habits for a healthier smile', 'small-habits-healthier-smile', 'A steady routine can make looking after your smile feel more manageable.', 'A consistent brush-and-floss routine, regular checkups, and honest conversations can go a long way. If something feels confusing, bring it up at your next visit. Good care starts with understanding.', '/images/blog-small-moments.svg', 'A sunlit still life with a flower and warm cup', 'Everyday care', 'published', now()) ON CONFLICT (site_id, slug) DO NOTHING;
INSERT INTO tele_blog_posts (site_id, title, slug, excerpt, body, feature_image_url, feature_image_alt, category, status, published_at) VALUES ('brightside-dental-studio', 'What to expect at a checkup', 'what-to-expect-at-a-checkup', 'Knowing what happens next can make a routine appointment feel easier.', 'We will review your concerns, explain what we are checking, and pause whenever you need. You will leave with a clear summary and a chance to talk through any options.', '/images/blog-care-team.svg', 'A practice team and companion in a calm room', 'Your visit', 'published', now()) ON CONFLICT (site_id, slug) DO NOTHING;
